import { action, makeObservable, observable } from 'mobx';
import { search, set, remove, get } from '@api'; // Импортируем ваши методы
import { notify } from '@utils';
import { collection, doc } from 'firebase/firestore';
import { db } from '../firebase.ts';

type Celebrant = {
	name: string;
	photo: string;
	message: string;
}

type Gift = {
	id: string;
	name: string;
	link: string;
	image: string;
	weight?: number;
	bookedByUser?: string;
};

class CollectionsStore {
	celebrant: Celebrant = null;

	codes: string[] = [];
	codesPage: number = 1;

	gifts: Gift[] = [];
	giftsPage: number = 1;
	giftsOrder: 'name' | 'weight' = 'weight';
	giftsDirection: 'asc' | 'desc' = 'asc';

	loading: boolean = false;

	constructor() {
		makeObservable(this, {
			celebrant: observable,
			codes: observable,
			gifts: observable,
			loading: observable,
			codesPage: observable,
			giftsPage: observable,

			giftsOrder: observable,
			giftsDirection: observable,

			setCelebrant: action,
			setCelebrantField: action,
			setCodes: action,
			setGifts: action,
			setLoading: action,
			setCodesPage: action,
			setGiftsPage: action,

			setGiftsOrder: action,
		});
	}

	setCelebrant = (celebrant: Celebrant) => {
		this.celebrant = celebrant;
	};

	setCelebrantField = (field: string, value: string) => {
		if (this.celebrant) {
			this.celebrant[field] = value;
		}
	};

	setCodes = (codes: string[]) => {
		this.codes = codes;
	};

	setGifts = (gifts: Gift[]) => {
		this.gifts = gifts;
	};

	setLoading = (state: boolean) => {
		this.loading = state;
	};

	setCodesPage = (page: number) => {
		this.codesPage = page;
	};

	setGiftsPage = (page: number) => {
		this.giftsPage = page;
	};

	saveCelebrant = async () => {
		if (!this.celebrant) {
			return;
		}

		try {
			await set('celebrant', 'info', this.celebrant);

			notify({
				variant: 'success',
				message: 'Данные именинника обновлены!',
			});
		} catch (error) {
			console.log(error);
			notify({
				variant: 'error',
				message: 'Не удалось сохранить данные',
			});
		}
	};

	createCode = async () => {
		try {
			const newId = doc(collection(db, 'codes')).id;

			await set('codes', newId, {});

			this.setCodes([newId, ...this.codes]);

			notify({
				variant: 'success',
				message: `Код ${newId} успешно создан!`,
			});
		} catch (error) {
			console.log(error);
			notify({
				variant: 'error',
				message: 'Ошибка при создании кода',
			});
		}
	};

	deleteCode = async (id: string) => {
		if (!window.confirm(`Удалить код ${id}?`)) {
			return;
		}

		try {
			await remove('codes', [{ field: '__name__', op: '==', value: id }]);

			this.setCodes(this.codes.filter(codeId => codeId !== id));

			notify({
				variant: 'success',
				message: 'Код удален',
			});
		} catch (error) {
			console.log(error);
			notify({
				variant: 'error',
				message: 'Ошибка удаления кода',
			});
		}
	};

	setGiftsOrder = async (field: 'name' | 'weight') => {
		if (this.giftsOrder === field) {
			this.giftsDirection = this.giftsDirection === 'asc' ? 'desc' : 'asc';
		} else {
			this.giftsOrder = field;
			this.giftsDirection = 'asc';
		}
		await this.fetchGifts();
	};

	fetchGifts = async () => {
		try {
			const gifts = await search('gifts', { order: [{ field: this.giftsOrder, direction: this.giftsDirection }] });

			this.setGifts(gifts);
		} catch (error) {
			console.log(error);
			notify({
				variant: 'error',
				message: 'Ошибка загрузки подарков',
			});
		}
	};

	saveGift = async (giftData: any, id?: string) => {
		try {
			const finalId = id || doc(collection(db, 'gifts')).id;

			await set('gifts', finalId, giftData);

			await this.fetchGifts();

			notify({
				variant: 'success',
				message: id ? 'Подарок изменен' : 'Подарок создан',
			});
		} catch (error) {
			console.log(error);
			notify({
				variant: 'error',
				message: 'Ошибка сохранения подарка',
			});
		}
	};

	deleteGift = async (id: string) => {
		if (!window.confirm('Удалить этот подарок?')) {
			return;
		}

		try {
			await remove('gifts', [{ field: '__name__', op: '==', value: id }]);

			await this.fetchGifts();

			notify({
				variant: 'success',
				message: 'Подарок удален',
			});
		} catch (error) {
			console.log(error);
			notify({
				variant: 'error',
				message: 'Ошибка удаления',
			});
		}
	};

	fetchAllData = async () => {
		this.setLoading(true);

		try {
			const [
				{ id, ...celebrant },
				codes,
			] = await Promise.all([
				get('celebrant', 'info'),
				search('codes'),
				this.fetchGifts(),
			]);

			this.setCelebrant(celebrant);
			this.setCodes(codes.map(({ id }) => id));
		} catch (error) {
			console.log(error);
			notify({
				variant: 'error',
				message: 'Ошибка при загрузке данных админки',
			});
		} finally {
			this.setLoading(false);
		}
	};
}

export default CollectionsStore;
