import React from 'react';
import { HashRouter } from 'react-router-dom'; // on normal host change to BrowserRouter
import { magic } from '@utils';
import Router from './router';
import { Loader } from '@ui';
import s from '@styles/main.scss';
import '@styles/fonts/Supercell-Magic.ttf';

interface App {
	loading: boolean;
	checkAuth: () => void;
}

const App = ({ loading, checkAuth }: App): React.ReactElement => {
	React.useEffect(() => {
		checkAuth();
	}, []);

	if (loading) {
		return <Loader/>;
	}

	return (
		<HashRouter>
			<Router/>
		</HashRouter>
	);
};

const mapStore = ({ UserStore }): App => {
	return {
		loading: UserStore.loading,
		checkAuth: UserStore.checkAuth,
	};
};

export default magic(App, { store: mapStore, styles: s });
