import React from 'react';
import { icons } from './svg';
import { SvgIcon } from '@mui/material';
import { notify } from '@utils';
import { SvgIconProps } from '@mui/material/SvgIcon/SvgIcon';

interface IconProps extends SvgIconProps {
	type: 'brands' | 'duotone' | 'light' | 'regular' | 'solid';
	name: string;
	size?: 'inherit' | 'large' | 'medium' | 'small' | number;
	className?: string;
}

const Icon = React.forwardRef(({ type, name, size, className }: IconProps, ref) => {
	if (!type || !name) {
		notify({
			variant: 'warning',
			message: 'Props "type" and "name" is required in Icon component',
		});

		return null;
	}

	const currentIcon: { path: string, viewBox: string } = icons[type]?.[name];

	if (!currentIcon) {
		notify({
			variant: 'warning',
			message: `Icon with type "${type}" and name "${name}" is not found`,
		});

		return null;
	}

	const innerProps: {
		fontSize?: 'inherit' | 'large' | 'medium' | 'small';
		sx?: { fontSize?: number }
	} = {};

	const { viewBox, path } = currentIcon;

	if (['inherit', 'large', 'medium', 'small'].includes(size)) {
		innerProps.fontSize = size;
	}

	if (size && typeof size === 'number') {
		innerProps.sx = {
			fontSize: size,
		};
	}

	return (
		<SvgIcon
			ref={ref}
			viewBox={viewBox}
			className={className}
			fontSize={innerProps.fontSize}
			sx={innerProps.sx}
		>
			<path d={path}/>
		</SvgIcon>
	);
});

Icon.displayName = 'Icon';

export default Icon;
