import React from 'react';
import { magic } from '@utils';
import s from './Input.scss';

interface InputProps {
	value: string;
	onChange: Function;
	placeholder?: string;
}

const Input = ({ value, type, onChange, placeholder }: InputProps) => {
	return (
		<div className={s.container}>
			<input
				className={s.input}
				value={value}
				type={type}
				onChange={onChange}
				placeholder={placeholder}
			/>
		</div>
	);
};

export default magic(Input, { styles: s });
