import { makeObservable, observable, action, computed } from 'mobx';
import { onAuthStateChanged, signOut, UserCredential } from 'firebase/auth';
import { get, signIn, signUp } from '@api';
import { auth } from '../firebase';
import { notify } from '@utils';

export interface UserStoreI {
	code: string;
	user: UserCredential['user'] | null;
	loading: boolean;

	get isValidCode(): boolean;

	setCode({ target }: Event): void;

	setUser(user: UserCredential['user']): void;

	setLoading(state: boolean): void;

	checkCode(): Promise<void>;

	checkAuth(): void;

	logOut(): Promise<void>;
}

export default class UserStore implements UserStoreI {
	code: string = '';

	user: UserCredential['user'] = null;

	loading: boolean = true;

	constructor() {
		makeObservable(this, {
			code: observable,
			user: observable,
			loading: observable,

			isValidCode: computed,

			setCode: action,
			setUser: action,
			setLoading: action,
		});
	}

	get isValidCode() {
		return this.code.length >= 5;
	}

	setCode = ({ target }) => {
		this.code = target.value.trim();
	};

	setUser = (user: UserCredential['user'] | null) => {
		this.user = user;
	};

	setLoading = (state: boolean) => {
		this.loading = state;
	};

	checkCode = async () => {
		if (!this.code) {
			notify({
				variant: 'error',
				message: 'Введите код',
			});

			return;
		}

		this.setLoading(true);

		try {
			const isCodeValid = await get('codes', this.code);

			if (!isCodeValid) {
				notify({
					variant: 'error',
					message: 'Введён неверный код',
				});

				this.setLoading(false);

				return;
			}

			const email = `${this.code}@mail.com`;
			const password = `pass${this.code}`;
			let currentUser: UserCredential['user'];

			try {
				// Пытаемся зарегистрировать нового пользователя
				currentUser = await signUp(email, password);
			} catch (signUpError: any) {
				// Если аккаунт уже создан, просто авторизуем его
				if (['auth/email-already-in-use', 'auth/email-already-in-check'].includes(signUpError.code)) {
					currentUser = await signIn(email, password);
				} else {
					throw signUpError;
				}
			}

			this.setUser(currentUser);
		} catch (err) {
			notify({
				variant: 'error',
				message: 'Что-то пошло не так! Обратитесь к администратору',
			});
		} finally {
			this.setLoading(false);
		}
	};

	checkAuth = () => {
		onAuthStateChanged(auth, (user) => {
			this.setUser(user);
			this.setLoading(false);

			return user;
		});
	};

	logOut = () => signOut(auth);
}
