import React from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { UserCredential } from 'firebase/auth';
import { magic, ROUTES } from '@utils';
import { authRoutes, publicRoutes } from './routes';

const route = ({ path, element }: RouteProps) => (
	<Route
		key={path}
		path={path}
		element={element}
	/>
);

const Router = ({ user }: RouterProps) => (
	<Routes>
		{
			user && authRoutes.map(route)
		}
		{
			publicRoutes.map(route)
		}
		<Route
			path={'*'}
			element={
				<Navigate to={user ? ROUTES.NOT_FOUND_404 : ROUTES.SIGN_IN}/>
			}
		/>
	</Routes>
);

const mapStore = ({ UserStore }) => {
	return {
		user: UserStore.user,
	};
};

type RouteProps = {
	path: string;
	element: React.ReactNode;
}

type RouterProps = {
	user?: UserCredential['user'] | null;
}

export default magic(Router, { store: mapStore });
