import React from 'react';
import AdminAuth from './auth.tsx';
import { magic } from '@utils';
import s from './style.scss';
import { Loader } from '@ui';

const PAGE_SIZE = 20;

const AdminPage = ({
										 admin,
										 celebrant,
										 codes,
										 codesPage,
										 gifts,
										 giftsPage,
										 giftsOrder,
										 giftsDirection,
										 loading,
										 fetchAllData,
										 setCelebrantField,
										 saveCelebrant,
										 createCode,
										 deleteCode,
										 saveGift,
										 deleteGift,
										 setCodesPage,
										 setGiftsPage,
										 setGiftsOrder,
									 }) => {
	const [isModalOpen, setIsModalOpen] = React.useState(false);
	const [editingGift, setEditingGift] = React.useState<any>(null);
	const [giftForm, setGiftForm] = React.useState({ name: '', image: '', link: '', weight: 0, bookedByUser: '' });

	React.useEffect(() => {
		if (admin) {
			fetchAllData();
		}
	}, [admin]);

	if (!admin) {
		return <AdminAuth />;
	}

	if (loading || !celebrant) {
		return <Loader />;
	}

	const totalCodesPages = Math.ceil(codes.length / PAGE_SIZE) || 1;
	const paginatedCodes = codes.slice((codesPage - 1) * PAGE_SIZE, codesPage * PAGE_SIZE);

	const totalGiftsPages = Math.ceil(gifts.length / PAGE_SIZE) || 1;
	const paginatedGifts = gifts.slice((giftsPage - 1) * PAGE_SIZE, giftsPage * PAGE_SIZE);

	const openGiftModal = (gift = null) => {
		if (gift) {
			setEditingGift(gift);

			setGiftForm({
				name: gift.name || '',
				image: gift.image || '',
				link: gift.link || '',
				weight: Number(gift.weight) || 0,
				bookedByUser: gift.bookedByUser || '',
			});
		} else {
			setEditingGift(null);

			setGiftForm({
				name: '',
				image: '',
				link: '',
				weight: 0,
				bookedByUser: '',
			});
		}
		setIsModalOpen(true);
	};

	const handleGiftSubmit = (event) => {
		event.preventDefault();

		saveGift(giftForm, editingGift ? editingGift.id : null);

		setIsModalOpen(false);
	};

	return (
		<div className={s.adminPage}>
			<h1>{'Панель администратора'}</h1>

			{/* БЛОК 1: ИМЕНИННИК (CELEBRANT) */}
			<section className={s.section}>
				<h2>{'Данные именинника (Коллекция: celebrant)'}</h2>
				<div className={s.formGroup}>
					<label>{'Имя:'}</label>
					<input
						value={celebrant.name}
						onChange={({ target }) => setCelebrantField('name', target.value)}
					/>
				</div>
				<div className={s.formGroup}>
					<label>{'Ссылка на фото:'}</label>
					<input
						value={celebrant.photo}
						onChange={({ target }) => setCelebrantField('photo', target.value)}
					/>
				</div>
				<div className={s.formGroup}>
					<label>{'Приветственное сообщение (HTML):'}</label>
					<textarea
						rows={20}
						value={celebrant.message}
						onChange={({ target }) => setCelebrantField('message', target.value)}
						className={s.textarea}
					/>
				</div>
				<button
					type="button"
					color="yellow"
					onClick={saveCelebrant}
				>
					{'Сохранить изменения именинника'}
				</button>
			</section>

			{/* БЛОК 2: КОДЫ (CODES) */}
			<section className={s.section}>
				<h2>{'Коды доступа (Коллекция: codes)'}</h2>
				<div className={s.actionBar}>
					<button
						type="button"
						color="yellow"
						onClick={createCode}
					>
						{'Сгенерировать новый код'}
					</button>
				</div>

				<table className={s.table}>
					<thead>
					<tr>
						<th>ID Кода</th>
						<th>Действия</th>
					</tr>
					</thead>
					<tbody>
						{
							paginatedCodes.map(code => (
								<tr key={code}>
									<td><code>{code}</code></td>
									<td>
										<button
											onClick={() => deleteCode(code)}
											className={s.deleteBtn}
										>
											{'Удалить'}
										</button>
									</td>
								</tr>
							))
						}
					</tbody>
				</table>

				{/* Пагинация кодов */}
				<div className={s.pagination}>
					<button
						disabled={codesPage === 1}
						onClick={() => setCodesPage(codesPage - 1)}
					>
						{'Назад'}
					</button>
					<span>{`Страница ${codesPage} из ${totalCodesPages}`}</span>
					<button
						disabled={codesPage === totalCodesPages}
						onClick={() => setCodesPage(codesPage + 1)}
					>
						{'Вперед'}
					</button>
				</div>
			</section>

			{/* БЛОК 3: ПОДАРКИ (GIFTS) */}
			<section className={s.section}>
				<h2>{'Список подарков (Коллекция: gifts)'}</h2>
				<div className={s.actionBar}>
					<button
						type="button"
						color="yellow"
						onClick={() => openGiftModal()}
					>
						{'Создать подарок'}
					</button>
				</div>

				<table className={s.table}>
					<thead>
					<tr>
						<th
							onClick={() => setGiftsOrder('name')}
							className={s.sortableHead}
						>
							{`Название ${giftsOrder === 'name' ? (giftsDirection === 'asc' ? '▲' : '▼') : ''}`}
						</th>
						<th>{'Изображение'}</th>
						<th>{'Ссылка'}</th>
						<th
							onClick={() => setGiftsOrder('weight')}
							className={s.sortableHead}
						>
							{`Вес / Приоритет ${giftsOrder === 'weight' ? (giftsDirection === 'asc' ? '▲' : '▼') : ''}`}
						</th>
						<th>{'Статус брони'}</th>
						<th>{'Действия'}</th>
					</tr>
					</thead>
					<tbody>
						{
							paginatedGifts.map(gift => (
								<tr key={gift.id}>
									<td>{gift.name}</td>
									<td><img src={gift.image} alt={gift.name} className={s.tableImg} /></td>
									<td><a href={gift.link} target="_blank" rel="noreferrer">Открыть ссылку</a></td>
									<td>{gift.weight}</td>
									<td>{gift.bookedByUser ? `Забронирован (${gift.bookedByUser})` : 'Свободен'}</td>
									<td>
										<button onClick={() => openGiftModal(gift)} className={s.editBtn}>Править</button>
										<button onClick={() => deleteGift(gift.id)} className={s.deleteBtn}>Удалить</button>
									</td>
								</tr>
							))
						}
					</tbody>
				</table>

				{/* Пагинация подарков */}
				<div className={s.pagination}>
					<button disabled={giftsPage === 1} onClick={() => setGiftsPage(giftsPage - 1)}>Назад</button>
					<span>Страница {giftsPage} из {totalGiftsPages}</span>
					<button disabled={giftsPage === totalGiftsPages} onClick={() => setGiftsPage(giftsPage + 1)}>Вперед</button>
				</div>
			</section>

			{/* МОДАЛЬНОЕ ОКНО ДЛЯ ПОДАРКА */}
			{
				isModalOpen && (
					<div className={s.modalOverlay}>
						<div className={s.modalContent}>
							<h3>{editingGift ? 'Редактировать подарок' : 'Создать новый подарок'}</h3>
							<form onSubmit={handleGiftSubmit}>
								<div className={s.formGroup}>
									<label>Название подарка:</label>
									<input value={giftForm.name} onChange={({ target }) => setGiftForm({ ...giftForm, name: target.value })} required />
								</div>
								<div className={s.formGroup}>
									<label>Ссылка на картинку:</label>
									<input value={giftForm.image} onChange={({ target }) => setGiftForm({ ...giftForm, image: target.value })} required />
								</div>
								<div className={s.formGroup}>
									<label>Ссылка на магазин (Ozon и др.):</label>
									<input value={giftForm.link} onChange={({ target }) => setGiftForm({ ...giftForm, link: target.value })} required />
								</div>
								<div className={s.formGroup}>
									<label>Вес (Сортировка):</label>
									<input type="number" value={giftForm.weight} onChange={({ target }) => setGiftForm({ ...giftForm, weight: Number(target.value) })} required />
								</div>
								<div className={s.modalButtons}>
									<button type="submit" color="yellow">{editingGift ? 'Сохранить' : 'Создать'}</button>
									<button type="button" onClick={() => setIsModalOpen(false)}>Отмена</button>
								</div>
							</form>
						</div>
					</div>
				)
			}
		</div>
	);
};

const mapStore = ({ AdminStore, CollectionsStore }) => {
	return {
		admin: AdminStore.admin,
		celebrant: CollectionsStore.celebrant,
		codes: CollectionsStore.codes,
		codesPage: CollectionsStore.codesPage,
		gifts: CollectionsStore.gifts,
		giftsPage: CollectionsStore.giftsPage,
		giftsOrder: CollectionsStore.giftsOrder,
		giftsDirection: CollectionsStore.giftsDirection,
		loading: CollectionsStore.loading,
		fetchAllData: CollectionsStore.fetchAllData,
		setCelebrantField: CollectionsStore.setCelebrantField,
		saveCelebrant: CollectionsStore.saveCelebrant,
		createCode: CollectionsStore.createCode,
		deleteCode: CollectionsStore.deleteCode,
		saveGift: CollectionsStore.saveGift,
		deleteGift: CollectionsStore.deleteGift,
		setCodesPage: CollectionsStore.setCodesPage,
		setGiftsPage: CollectionsStore.setGiftsPage,
		setGiftsOrder: CollectionsStore.setGiftsOrder,
	};
};

export default magic(AdminPage, { store: mapStore, styles: s });
