import { makeObservable, observable, action, computed } from 'mobx';
import { notify } from '@utils';
import { get, set } from '@api';
import { UserStoreI } from './userStore';

/**
 * Подарок
 * @property id - ID записи в firebase
 * @property name - Наименование подарка
 * @property link - Ссылка на подарок (например на маркетплейс)
 * @property image - Ссылка на изображение подарка
 * @property weight - Вес (для сортировки)
 * @property bookedByUser - Почта юзера, который выбрал подарок, чтобы подарить
 */
type Gift = {
	id: string;
	name: string;
	link: string;
	image: string;
	weight?: number;
	bookedByUser?: string;
};

type Celebrant = {
	name: string;
	photo: string;
	message: string;
}

class GiftStore {
	celebrant: Celebrant = null;

	UserStore: UserStoreI;

	gifts: Gift[] = [];

	loading = false;

	constructor({ UserStore }) {
		makeObservable(this, {
			celebrant: observable,
			gifts: observable,
			loading: observable,

			canBookedGifts: computed,

			setCelebrant: action,
			setGifts: action,
			setLoading: action,
		});

		this.UserStore = UserStore;

		this.getCelebrant();
	}

	get canBookedGifts() {
		const { user } = this.UserStore;

		return this.gifts.filter(({ bookedByUser }) => bookedByUser === user?.email).length <= 2;
	}

	// ACTIONS

	setCelebrant = (celebrant: Celebrant) => {
		this.celebrant = celebrant;
	};

	setGifts = (gifts: Gift[]) => {
		this.gifts = gifts;
	};

	setLoading = (loading: boolean) => {
		this.loading = loading;
	};

	// REQUESTS

	getCelebrant = async () => {
		try {
			const celebrant = await get('celebrant', 'info');

			this.setCelebrant(celebrant as Celebrant);
		} catch (error) {
			return notify({
				variant: 'error',
				message: 'Не удалось получить информацию об имениннике',
			});
		}
	}

	bookGift = async (gift: Gift) => {
		const { user } = this.UserStore;

		if (!user?.email) {
			return notify({
				variant: 'error',
				message: 'Не удалось. Обновите страницу и попробуйте ещё раз',
			});
		}

		const { id, ...data } = gift;

		data.bookedByUser = data.bookedByUser === user.email ?
			'' :
			user.email;

		await set('gifts', id, data);
	};
}

export default GiftStore;
