import { action, makeObservable, observable } from 'mobx';
import { UserCredential } from 'firebase/auth';
import { notify } from '@utils';
import { signIn } from '@api';
import { FIREBASE_ERRORS } from '@utils';

class AdminStore {
	admin: UserCredential['user'] = null;

	login: string = '';

	password: string = '';

	loading: boolean = true;

	constructor() {
		makeObservable(this, {
			admin: observable,
			login: observable,
			password: observable,
			loading: observable,

			setAdmin: action,
			setLogin: action,
			setPassword: action,
			setLoading: action,
		});
	}

	setAdmin = (admin: UserCredential['user']) => {
		this.admin = admin;
	};

	setLogin = ({ target }) => {
		this.login = target.value.trim();
	};

	setPassword = ({ target }) => {
		this.password = target.value.trim();
	};

	setLoading = (state: boolean) => {
		this.loading = state;
	};

	signIn = async () => {
		if (!this.login || !this.password) {
			notify({
				variant: 'error',
				message: 'Введи логин и пароль',
			});

			return;
		}

		this.setLoading(true);

		try {
			const admin = await signIn(this.login, this.password);

			this.setAdmin(admin);
		} catch (error) {
			notify({
				variant: 'error',
				message: FIREBASE_ERRORS[error] || error,
			});
		} finally {
			this.setLoading(false);
		}
	};
}

export default AdminStore;
