import React from 'react';
import { magic } from '@utils';
import s from './style.scss';

const Intro = ({ celebrant }) => {
	if (!celebrant) {
		return null;
	}

	return (
		<div className={s.intro}>
			<img
				className={s.photo}
				src={celebrant.photo}
				alt={celebrant.name}
			/>
			<div
				className={s.message}
				dangerouslySetInnerHTML={{ __html: celebrant.message }}
			/>
		</div>
	);
};

const mapStore = ({ GiftStore }) => {
	return {
		celebrant: GiftStore.celebrant,
	};
};


export default magic(Intro, { store: mapStore, styles: s });
