import React from 'react';
import { Navigate } from 'react-router-dom';
import { magic, ROUTES } from '@utils';
import { Input, Button } from '@ui';
import s from './style.scss';

const AdminAuth = ({ admin, login, setLogin, password, setPassword, signIn }) => {
	if (admin) {
		return <Navigate to={ROUTES.ADMIN} />;
	}

	return (
		<div className={s.page}>
			<div className={s.container}>
				<Input
					value={login}
					onChange={setLogin}
					placeholder={'Введи логин'}
				/>
				<Input
					value={password}
					type={'password'}
					onChange={setPassword}
					placeholder={'Введи пароль'}
				/>
				<div className={s.button}>
					<Button
						type={'button'}
						onClick={signIn}
						color={'yellow'}
					>
						{'Войти'}
					</Button>
				</div>
			</div>
		</div>
	);
};

const mapStore = ({ AdminStore }) => {
	return {
		login: AdminStore.login,
		password: AdminStore.password,
		setLogin: AdminStore.setLogin,
		setPassword: AdminStore.setPassword,
		signIn: AdminStore.signIn,
		user: AdminStore.admin,
	};
};

export default magic(AdminAuth, { store: mapStore, styles: s });
